INSERT INTO "business_parameters" ("key", "value", "valueType", "bounds", "unit", "ownerModule", "description", "version", "updatedAt") VALUES
  ('auth.passwordMinLength', '8'::jsonb, 'INT', '{"min": 8, "max": 64}'::jsonb, 'characters', 'auth', 'Minimum password length', 1, CURRENT_TIMESTAMP),
  ('auth.loginMaxFailures', '5'::jsonb, 'INT', '{"min": 3, "max": 20}'::jsonb, 'attempts', 'auth', 'Failed sign-ins inside the window that lock the account', 1, CURRENT_TIMESTAMP),
  ('auth.loginFailureWindowMinutes', '15'::jsonb, 'INT', '{"min": 1, "max": 120}'::jsonb, 'minutes', 'auth', 'Window in which failed sign-ins are counted', 1, CURRENT_TIMESTAMP),
  ('auth.lockoutMinutes', '15'::jsonb, 'INT', '{"min": 1, "max": 1440}'::jsonb, 'minutes', 'auth', 'How long a locked account stays locked', 1, CURRENT_TIMESTAMP),
  ('auth.resetCodeTtlMinutes', '10'::jsonb, 'INT', '{"min": 5, "max": 60}'::jsonb, 'minutes', 'auth', 'Lifetime of a password reset code', 1, CURRENT_TIMESTAMP),
  ('auth.invitationTtlHours', '72'::jsonb, 'INT', '{"min": 1, "max": 336}'::jsonb, 'hours', 'auth', 'Lifetime of an invitation (set-password) code', 1, CURRENT_TIMESTAMP),
  ('auth.codeMaxAttempts', '5'::jsonb, 'INT', '{"min": 1, "max": 10}'::jsonb, 'attempts', 'auth', 'Wrong entries before a code is spent', 1, CURRENT_TIMESTAMP),
  ('auth.codeResendCooldownSeconds', '60'::jsonb, 'DURATION_SECONDS', '{"min": 10, "max": 600}'::jsonb, 'seconds', 'auth', 'Minimum wait before another code is sent', 1, CURRENT_TIMESTAMP),
  ('organizations.maxApiKeys', '5'::jsonb, 'INT', '{"min": 1, "max": 50}'::jsonb, 'keys', 'organizations', 'Active API keys per organization', 1, CURRENT_TIMESTAMP),
  ('organizations.maxFieldStations', '5'::jsonb, 'INT', '{"min": 1, "max": 50}'::jsonb, 'credentials', 'organizations', 'Active Field Station credentials per organization', 1, CURRENT_TIMESTAMP),
  ('organizations.rosterMaxRangeDays', '31'::jsonb, 'INT', '{"min": 1, "max": 92}'::jsonb, 'days', 'organizations', 'Longest range one roster query returns', 1, CURRENT_TIMESTAMP),
  ('devices.handoverMinBatteryPct', '50'::jsonb, 'PERCENT', '{"min": 0, "max": 100}'::jsonb, 'percent', 'devices', 'Below this battery the handover needs an explicit acknowledgement (MSG19)', 1, CURRENT_TIMESTAMP),
  ('devices.stockTakeSeenHours', '24'::jsonb, 'INT', '{"min": 1, "max": 168}'::jsonb, 'hours', 'devices', 'A rented device heard within this window counts as confirmed in a stock-take', 1, CURRENT_TIMESTAMP),
  ('rentals.minOrderQuantity', '5'::jsonb, 'INT', '{"min": 1, "max": 100}'::jsonb, 'devices', 'rentals', 'Minimum order quantity per contract', 1, CURRENT_TIMESTAMP),
  ('rentals.dayPlanLengths', '[3, 4, 7]'::jsonb, 'JSON', NULL, 'days', 'rentals', 'Day-plan lengths offered', 1, CURRENT_TIMESTAMP),
  ('rentals.reservationExpiryHours', '48'::jsonb, 'INT', '{"min": 1, "max": 336}'::jsonb, 'hours', 'rentals', 'Approved but not handed over after this long: Staff and Manager are reminded', 1, CURRENT_TIMESTAMP),
  ('rentals.returnGraceHours', '24'::jsonb, 'INT', '{"min": 0, "max": 168}'::jsonb, 'hours', 'rentals', 'Grace after the return due time before OVERDUE and late fees', 1, CURRENT_TIMESTAMP),
  ('rentals.defaultAfterDays', '7'::jsonb, 'INT', '{"min": 1, "max": 60}'::jsonb, 'days', 'rentals', 'OVERDUE this long becomes DEFAULTED', 1, CURRENT_TIMESTAMP),
  ('rentals.termRolloverHourLocal', '9'::jsonb, 'INT', '{"min": 0, "max": 23}'::jsonb, 'hour (UTC+7)', 'rentals', 'Hour at which daily term and day-plan jobs run', 1, CURRENT_TIMESTAMP),
  ('billing.holdingFeeRatio', '0.5'::jsonb, 'DECIMAL', '{"min": 0.1, "max": 1}'::jsonb, 'ratio', 'billing', 'Share of a monthly term fee due at the term start', 1, CURRENT_TIMESTAMP),
  ('billing.dayPremium', '1.5'::jsonb, 'DECIMAL', '{"min": 1, "max": 5}'::jsonb, 'ratio', 'billing', 'Day-plan premium over the monthly rate per day', 1, CURRENT_TIMESTAMP),
  ('billing.lateFeePerDevicePerDayVnd', '50000'::jsonb, 'INT', '{"min": 0, "max": 10000000}'::jsonb, 'VND', 'billing', 'Late fee per device per started day after the grace', 1, CURRENT_TIMESTAMP),
  ('billing.damageApprovalThresholdVnd', '500000'::jsonb, 'INT', '{"min": 0, "max": 100000000}'::jsonb, 'VND', 'billing', 'Damage charges above this need an Admin other than the inspector', 1, CURRENT_TIMESTAMP),
  ('billing.sepayPaymentTtlMinutes', '30'::jsonb, 'INT', '{"min": 5, "max": 1440}'::jsonb, 'minutes', 'billing', 'A SePay payment request expires after this long', 1, CURRENT_TIMESTAMP),
  ('billing.sepayBankAccount', '"SANDBOX-0001"'::jsonb, 'JSON', NULL, NULL, 'billing', 'Receiving account shown in the VietQR (sandbox)', 1, CURRENT_TIMESTAMP),
  ('gatewaySync.retroTagGraceSeconds', '60'::jsonb, 'DURATION_SECONDS', '{"min": 0, "max": 600}'::jsonb, 'seconds', 'gateway-sync', 'Positions this long before an SOS text are tagged into its episode', 1, CURRENT_TIMESTAMP),
  ('incidents.correlationWindowSeconds', '300'::jsonb, 'DURATION_SECONDS', '{"min": 30, "max": 3600}'::jsonb, 'seconds', 'incidents', 'An SOS within this time of the episode''s last event joins it', 1, CURRENT_TIMESTAMP),
  ('incidents.cadenceCount', '6'::jsonb, 'INT', '{"min": 2, "max": 50}'::jsonb, 'positions', 'incidents', 'N: positions inside W that raise a suspected incident', 1, CURRENT_TIMESTAMP),
  ('incidents.cadenceWindowSeconds', '60'::jsonb, 'DURATION_SECONDS', '{"min": 10, "max": 600}'::jsonb, 'seconds', 'incidents', 'W: window for the cadence count', 1, CURRENT_TIMESTAMP),
  ('incidents.primaryAckTimeoutSeconds', '120'::jsonb, 'DURATION_SECONDS', '{"min": 30, "max": 900}'::jsonb, 'seconds', 'incidents', 'Primary tier acknowledge timeout', 1, CURRENT_TIMESTAMP),
  ('incidents.backupAckTimeoutSeconds', '120'::jsonb, 'DURATION_SECONDS', '{"min": 30, "max": 900}'::jsonb, 'seconds', 'incidents', 'Backup tier acknowledge timeout', 1, CURRENT_TIMESTAMP),
  ('incidents.managerAckTimeoutSeconds', '180'::jsonb, 'DURATION_SECONDS', '{"min": 30, "max": 1800}'::jsonb, 'seconds', 'incidents', 'Manager tier acknowledge timeout, then ESCALATED', 1, CURRENT_TIMESTAMP),
  ('incidents.staleLimitMinutes', '30'::jsonb, 'INT', '{"min": 5, "max": 240}'::jsonb, 'minutes', 'incidents', 'Longest gap between status updates of an owned incident', 1, CURRENT_TIMESTAMP),
  ('incidents.reopenWindowMinutes', '60'::jsonb, 'INT', '{"min": 5, "max": 1440}'::jsonb, 'minutes', 'incidents', 'A new SOS inside this window after RESOLVED or FALSE_ALARM reopens', 1, CURRENT_TIMESTAMP),
  ('incidents.alertMaxAttempts', '5'::jsonb, 'INT', '{"min": 1, "max": 20}'::jsonb, 'attempts', 'incidents', 'Delivery attempts per alert before FAILED', 1, CURRENT_TIMESTAMP),
  ('incidents.alertRetryBaseSeconds', '5'::jsonb, 'DURATION_SECONDS', '{"min": 1, "max": 300}'::jsonb, 'seconds', 'incidents', 'Base of the exponential retry backoff', 1, CURRENT_TIMESTAMP),
  ('monitoring.deviceStaleSeconds', '300'::jsonb, 'DURATION_SECONDS', '{"min": 30, "max": 7200}'::jsonb, 'seconds', 'monitoring', 'A device silent this long is shown stale', 1, CURRENT_TIMESTAMP),
  ('monitoring.fieldStationStaleSeconds', '180'::jsonb, 'DURATION_SECONDS', '{"min": 30, "max": 7200}'::jsonb, 'seconds', 'monitoring', 'A Field Station silent this long is shown stale', 1, CURRENT_TIMESTAMP),
  ('monitoring.staleSweepSeconds', '15'::jsonb, 'DURATION_SECONDS', '{"min": 5, "max": 300}'::jsonb, 'seconds', 'monitoring', 'Cadence of the staleness sweep', 1, CURRENT_TIMESTAMP),
  ('monitoring.maxPlausibleSpeedKmh', '30'::jsonb, 'INT', '{"min": 5, "max": 300}'::jsonb, 'km/h', 'monitoring', 'Positions implying a faster move are not plotted', 1, CURRENT_TIMESTAMP),
  ('monitoring.positionBounds', '{"minLat": 8.0, "maxLat": 23.5, "minLon": 102.0, "maxLon": 110.0}'::jsonb, 'JSON', NULL, 'degrees', 'monitoring', 'Positions outside this box are rejected', 1, CURRENT_TIMESTAMP),
  ('monitoring.positionEmitMinIntervalMs', '1000'::jsonb, 'INT', '{"min": 0, "max": 60000}'::jsonb, 'milliseconds', 'monitoring', 'Minimum interval between position pushes per device', 1, CURRENT_TIMESTAMP),
  ('monitoring.streamRetentionHours', '72'::jsonb, 'INT', '{"min": 1, "max": 720}'::jsonb, 'hours', 'monitoring', 'Stream entries older than this are pruned; older cursors get 410', 1, CURRENT_TIMESTAMP),
  ('monitoring.apiRateLimitPerMinute', '120'::jsonb, 'INT', '{"min": 10, "max": 6000}'::jsonb, 'requests', 'monitoring', 'Organization API requests per key per minute', 1, CURRENT_TIMESTAMP),
  ('monitoring.mapProvider', '"openstreetmap"'::jsonb, 'JSON', NULL, NULL, 'monitoring', 'Map provider identifier (D-031)', 1, CURRENT_TIMESTAMP),
  ('monitoring.mapTileUrl', '"https://tile.openstreetmap.org/{z}/{x}/{y}.png"'::jsonb, 'JSON', NULL, NULL, 'monitoring', 'Tile URL template', 1, CURRENT_TIMESTAMP),
  ('monitoring.mapAttribution', '"© OpenStreetMap contributors"'::jsonb, 'JSON', NULL, NULL, 'monitoring', 'Attribution shown on the map', 1, CURRENT_TIMESTAMP),
